{
  "themes": [
    {
      "cluster": 24,
      "name": "OnePlus 5 Exchange & EMI Issues",
      "description": "Customers report discrepancies in exchange offers, hidden EMI charges, and confusion regarding device-specific promotions."
    },
    {
      "cluster": 25,
      "name": "Excessive Packaging Waste",
      "description": "Users complain about receiving items in disproportionately large boxes, citing environmental waste and unnecessary cardboard."
    },
    {
      "cluster": 26,
      "name": "Unexplained Duplicate Charges",
      "description": "Customers report being charged extra or twice for orders, subscriptions, or returned items despite cancellations."
    },
    {
      "cluster": 27,
      "name": "Gift Card Balance Errors",
      "description": "Users experience issues where gift cards fail to add, balances do not update correctly, or vouchers are reported as invalid."
    },
    {
      "cluster": 28,
      "name": "Amazon Pay Withdrawal Restrictions",
      "description": "Customers seek to transfer Amazon Pay balances to bank accounts or question why funds are held in the wallet."
    },
    {
      "cluster": 29,
      "name": "Missing Cashback Credits",
      "description": "Users report that promised cashback offers were not credited to their accounts after completing eligible purchases."
    },
    {
      "cluster": 30,
      "name": "Wrong or Damaged Items",
      "description": "Customers receive incorrect products, damaged goods, or face difficulties getting replacements for defective orders."
    },
    {
      "cluster": 31,
      "name": "Unhelpful Customer Support",
      "description": "Users express frustration with unhelpful, confusing, or dismissive interactions with customer service representatives."
    },
    {
      "cluster": 32,
      "name": "General Technical Errors",
      "description": "Customers report various app or website glitches and seek assistance with unclear error messages or functionality."
    },
    {
      "cluster": 33,
      "name": "Delayed Refund Processing",
      "description": "Users complain that refunds are not received within the expected timeframe after returning items or cancelling orders."
    },
    {
      "cluster": 34,
      "name": "Order Cancellation Failures",
      "description": "Customers are unable to cancel orders due to page loading errors or confusion about cancellation windows."
    },
    {
      "cluster": 35,
      "name": "Poor Service Attitude",
      "description": "Customers describe customer service interactions as rude, unprofessional, or lacking in follow-through."
    }
  ]
}
